INSERT INTO theory_content (chapter_slug, subject_id, concepts_json) VALUES ('telangana-history-en-chapter28-police-action-operation-polo', 'telangana-history-en', '') ON CONFLICT(chapter_slug) DO UPDATE SET concepts_json = '';
UPDATE theory_content SET concepts_json = concepts_json || '[{"partNumber": 1, "conceptId": "telangana-history-en-chapter28-police-action-operation-polo-p1", "partName": "Hyderabad''s Princely Status and the Early Demand for Merger", "bodyMd": "When India became independent on **15th August, 1947**, the state of Hyderabad did not merge into the Union of India. At independence, India had **562 princely states**; all but four of these were integrated into the Indian Union soon after independence. The four holdouts were:\n\n1. **Travancore** (Kerala)\n2. **Junagadh** (Gujarat)\n3. **Kashmir** (Jammu & Kashmir)\n4. **Hyderabad**\n\nOf these four, Hyderabad was the largest. Its eventual merger came about through a police action on **17th September, 1948**, code-named **\"Operation Polo,\"** which brought Nizam rule to an end.\n\nHyderabad''s freedom movement was not seen by Swamiji (the movement''s leadership) as a purely regional issue — India''s final struggle for freedom was understood to be continuing on Hyderabad soil, and this was seen as requiring the support of all Indians.\n\n- **Ayyadevara Kaleswara Rao** headed the Hyderabad State Congress Committee, which belonged to the Andhra Rashtriya Congress; funds for the movement were collected from Andhra people and passed on to Swamiji.\n- On **27th December, 1947**, a \"Hyderabad Sahayaka Samithi\" (Hyderabad Aid Committee) was formed in Madras, chaired by the Madras Mayor **Sri Krishna**, with **Venkataswaminaidu** and **Smt. Ammu Swaminathan** as vice-presidents and **Pappu Somasundaram** as secretary.\n- Separately, in **June 1946**, a conference of princely-state representatives was held under the chairmanship of **Jawaharlal Nehru**, following the British government''s announcement earlier that year that independence would be granted to India.\n  - Hyderabad State Congress members who attended: **Swamy Ramananda Tirtha** and **Burgula Ramakrishna Rao**.\n  - Andhra Maha Sabha members who took part: **Raavi Narayana Reddy** and **Laxmi Narsaiah**.\n  - All of them expressed the intention of merging Hyderabad state with the Indian Union.\n- At a public meeting in **Guntur** on **21st June, 1948**, **Jayaprakash Narayan** declared that there was no way to resolve Hyderabad''s problems except through war, and called for Hyderabad to be surrounded on three sides using the armies of the neighbouring states.\n- **Acharya Bhansali**, a close associate of Gandhiji at Sevagram, undertook a fast unto death in **Vijayawada** against the atrocities being committed on people by the Razakars in Telangana and the insults being inflicted on women; the Nizam government refused to allow him to enter the state.\n\nThe State Congress intensified its efforts and met the Nizam''s high-handedness with equal firmness; the Nizam''s kingdom turned into a powder keg. All parties, including Congress, carried the political struggle forward together on the principle that action follows conviction.", "free": true}, {"partNumber": 2, "conceptId": "telangana-history-en-chapter28-police-action-operation-polo-p2", "partName": "Jayaprakash Narayan''s Visit and the Nizam''s Declarations of Independence", "bodyMd": "- **7th May, 1947** — **Jayaprakash Narayan**, General Secretary of the Socialist Party, visited Hyderabad and addressed a public meeting at **Karbala Garden**, stating that Hyderabad state should merge with the Indian Union. Labour leaders **Madhav Singh** and **Narendra Prasad Saxena** also addressed the meeting.\n- The Nizam government, angered by Jayaprakash Narayan''s statement, expelled him from Hyderabad state.\n- The Hyderabad State Congress opposed this expulsion and agitated under a committee led by **Burgula Ramakrishna Rao**.\n- **12th June, 1947** — Nizam **Osman Ali Khan** declared himself a sovereign, independent ruler.\n- **13th August, 1947** — He again declared Hyderabad state to be an independent state.\n- During this period, the Nizam sent **Walter Monckton**, **Chattari Nawab**, and **Sultan Ahmed** to negotiate with **Mountbatten**.\n- **7th August, 1947** — Hyderabad State Congress leaders observed **\"Join India Union Day.\"**\n- **Sardar Vallabhbhai Patel** and **Nehru** subsequently mobilised armed forces around the boundaries of Hyderabad.\n- Faced with this pressure, the Nizam government entered into a **Standstill Agreement** with the Indian government.", "free": true}, {"partNumber": 3, "conceptId": "telangana-history-en-chapter28-police-action-operation-polo-p3", "partName": "The Standstill Agreement (1947)", "bodyMd": "- **29th November, 1947** — The Indian government and the Nizam signed the Standstill Agreement for a period of one year. The Nizam''s prime minister at this time was **Mehdi Yar Jung**.\n- Signatories: **Nizam Mir Osman Ali Khan** and Indian Governor-General **Lord Mountbatten**.\n- Under the agreement, **K.M. Munshi** was appointed as the Indian Government''s Agent-General in Hyderabad, and **Zain Yar Jung** was appointed as the Hyderabad Agent-General in Delhi.\n\n### Key Terms of the Agreement\n- All relations that existed between the Nizam and the British government before 15th August, 1947 would continue temporarily, unchanged, between the Nizam and the Indian government — hence the name \"Standstill Agreement.\"\n- Hyderabad''s defence, foreign affairs, and communications would come under Indian government control.\n- Indian currency would be valid in Hyderabad state.\n- Indian banks and insurance companies would be permitted to operate in the Nizam''s state.\n- Citizens of Hyderabad would be granted freedom of speech and freedom of assembly; arrested State Congress leaders, including **Ramananda Tirtha**, were to be released.\n- A democratic government was to be formed in Hyderabad within one year of the agreement.\n- If war broke out between India and Pakistan, Hyderabad was to remain neutral.\n\n### Attack on the Nizam\n- **4th December, 1947** — **Narayan Rao Pawar** of the Arya Samaj Kranti Kar Dal attacked Nizam Osman Ali Khan with a bomb at King Kothi, Hyderabad; the attack failed. Police arrested Narayan Rao Pawar, Jagadeeshwar, and Gandaiah; the seventh accused in the case was **Konda Laxman Bapuji**. Narayan Rao Pawar is remembered as the **\"Telangana Bhagat Singh.\"**\n- Mehdi Yar Jung resigned as prime minister on the very day the Standstill Agreement was signed; the Nizam then appointed **Laiq Ali** as prime minister.\n- **18th December, 1947** — The Nizam abolished the Council of Ministers and formed a new cabinet under Laiq Ali, which included four Hindu ministers:\n\n| Minister | Portfolio |\n|---|---|\n| Pingali Venkatrami Reddy | Deputy Prime Minister |\n| B.S. Venkatrao | — |\n| Mallikarjun Rao | — |\n| J.V. Joshi | — |\n\nLaiq Ali''s appointment marked the start of the breach of the Standstill Agreement.", "free": false}, {"partNumber": 4, "conceptId": "telangana-history-en-chapter28-police-action-operation-polo-p4", "partName": "Breach of the Standstill Agreement and India''s Response", "bodyMd": "- The Nizam government declared Indian currency invalid in Hyderabad state.\n- The Nizam sent **General Sayyed El Edroos** to Europe to purchase weapons.\n- **Sydney Cotton**, an Australian arms dealer, illegally supplied weapons to the Nizam from Goa; this illegal trade was brought to the Indian government''s notice by **Vandemataram Ramchandra Rao** and **Rama Rao**.\n- A separate ammunition deal was made with **T.T. Moore**, a former British army officer.\n- Prime Minister Laiq Ali attempted to purchase Goa from the Portuguese.\n- In violation of the treaty''s foreign-affairs clause, the Nizam gave a loan of **₹20 crores** to Pakistan out of Indian securities.\n- The Nizam''s last prime minister, Laiq Ali, coordinated with Pakistan''s first prime minister, **Liaquat Ali**, against India.\n- The Nizam set up ordinance factories to manufacture arms at **Moti Mahal, Golkonda,** and **Chaderghat**.\n- Consequently, the Indian government imposed financial restrictions on Hyderabad, and the Indian army took control of a place called **\"Nanaj\"** in Hyderabad state.\n- During this period the Nizam again sent Walter Monckton, Chattari Nawab, and Sultan Ahmed to negotiate with Mountbatten.\n\n## Indian Government''s Restrictions on Hyderabad\n\n- **Deccan Airways** of Hyderabad was banned, cutting off the state''s transport links and communication with the outside world.\n- Telephone lines were disrupted.\n- Restrictions were placed on Indian government securities held by Hyderabad; export of gold, diamonds, and coins from the state was banned.\n- Relations between the **Imperial Bank of India** and the Hyderabad State Bank were severed, worsening relations further.\n- Governor-General **Mountbatten** attempted mediation and sent his secretary **Allen Campbell** to Hyderabad to mediate, but this effort failed.\n\n## K.M. Munshi''s Negotiations\n\n- As agreed under the Standstill Agreement, **K.M. Munshi** was appointed Indian Government Agent-General in Hyderabad.\n- The Nizam, considering the Agent-General''s status unequal to that of a British Resident, refused to give Munshi the Residency building; Munshi instead stayed at **Deccan House, Bollaram**, an Indian government building.\n- Munshi urged the Nizam either to hold a plebiscite or to form a democratic government immediately.", "free": false}, {"partNumber": 5, "conceptId": "telangana-history-en-chapter28-police-action-operation-polo-p5", "partName": "Popular Resistance Inside Hyderabad", "bodyMd": "### Bhagya Nagar Radio\n- On the Nizam government''s **Deccan Radio**, Hyderabad Commander-in-Chief **Syed Ahmed El Edroos** warned the people to be prepared for all circumstances.\n- Since Deccan Radio was spreading false news, resistance leaders started the **Bhagya Nagar Radio** station to keep people informed with accurate news.\n- It was established by **Paaga Pulla Reddy**, operated as a secret radio station; socialist leader **Achyut Patwardhan** arranged the radio apparatus for Pulla Reddy in Bombay.\n- Broadcasts were made in **Telugu, English, and Urdu** — Telugu broadcasts by **Ramakrishna Sharma**, Urdu broadcasts by **T. Nagappa**.\n- These broadcasts raised awareness of Razakar and Nizam atrocities and helped stage protests against the Nizam; the Nizam government eventually banned the station.\n\n### Lawyers'' Agitation\n- Hyderabad''s lawyers agitated against Nizam rule, demanding merger with the Indian Union.\n- **February 1948** — a Lawyers'' Protest Committee was formed under **Vinayakarao Vidyalankar**.\n- Later, the **Nyayavadula Prathighatana Samithi** (Lawyers'' Resistance Committee) was formed under **Ganapathi Lal**, which wrote to the Nizam demanding a boycott of court duties.\n\n### Bakar Ali Mirza and the Muslim Appeal\n- Under **Bakar Ali Mirza''s** leadership, a number of Muslims wrote to the Nizam urging merger with India; the Nizam responded by placing Bakar Ali Mirza under house arrest.\n- **Sardar Vallabhbhai Patel** described Hyderabad as **\"an ulcer in the heart of India which needed to be removed surgically.\"**\n- As Indian Home Minister, Patel ordered Southern Commander-in-Chief **E.N. Goddard** to prepare a plan for police action on Hyderabad; Goddard drew up the plan and handed it to Patel.\n\n### The Congress Satyagraha Campaign\nThe State Congress intensified its own agitation alongside these efforts. Congress volunteers established satyagraha camps in **21** places in Madras province, **23** in Bombay province, and **4** in Madhya Pradesh, and carried out an anti-Razakar satyagraha campaign from them.\n\n**Camp leadership**\n- **Bejawada (Vijayawada) camp:** Jamalapuram Keshava Rao, V.B. Raju, T. Hayagrivachari\n- **Sholapur camp:** Konda Lakshmi\n- **Chanda camp:** P.V. Narasimha Rao\n\n**Scale of the movement**\n- **14,000** volunteers were arrested during this agitation.\n- **15,000** students boycotted schools.\n- **6,000** village officials resigned their posts.\n- Trees worth over **₹5 lakh**, planted to reduce the government''s excise revenue, were cut down entirely by the movement.\n- Various taxes levied by the Nizam government were prevented from being collected.\n- **615** police stations and Razakar camps were razed in this struggle.\n- Of **750** customs (\"cordon\") posts set up around the state''s artificial boundaries, **500** posts were destroyed.\n- Village defence forces (**Gramarakshaka Dalas**), formed for village protection, carried out **175** attacks on police and Razakars.\n- In this guerrilla struggle, **200** Razakars and Nizam policemen were killed.\n- Congress volunteers who lost their lives: **28** in Telangana, **22** in Marathwada, and **15** in Karnataka.\n\nThe struggle was directed from outside the state''s borders, with resistance camps set up in places like Bejawada, Sholapur, and Chanda, as listed above.", "free": false}, {"partNumber": 6, "conceptId": "telangana-history-en-chapter28-police-action-operation-polo-p6", "partName": "Razakar Propaganda on Deccan Radio", "bodyMd": "Razakar leader **Qasim Razvi** feared that his organisation would be entirely destroyed and wrote to his father — the Nizam''s second son, **Mohajanja** — asking for **₹5 crore** to be able to flee to a safe region of the country, but received no reply.\n\nRazvi also pinned many hopes on Pakistan. He sent a delegation under his brother-in-law **Mohin Nawaz Jung** to Karachi to meet **Jinnah**; owing to Jinnah''s illness, the delegation was not granted an interview.\n\nRazvi himself considered going to Karachi with no other option, but [Discrepancy between sources: Source 1 (English) — Jinnah died on 11th September, 1948; Source 2 (Telugu) — Jinnah died on 12th September, 1948 — needs verification]. The Police Action began on **13th September**, two days after Jinnah''s death.\n\nRazvi tried to deceive the Razakars and keep up their morale, entrusting overall command to Hyderabad''s Commander-in-Chief, **Major-General El Edroos**, even though Razvi himself did not have the army''s confidence. When the Razakars themselves complained that they needed proper weapons to fight, Razvi dismissed their concern and urged them to keep fighting on faith alone, insisting that victory would come regardless.\n\nThe weapons that actually reached the Razakars had, in truth, arrived through smuggling and were of no real use to trained soldiers, and the Razakars did not know how to use them properly. Razvi''s propaganda went further than even that of Hitler, and he kept the Deccan Radio firmly under his own control. Deccan Radio broadcast a number of false claims, including:\n\n1. If the Indian government initiated military action against Hyderabad, Muslim states such as Iran, Afghanistan, Pakistan, Turkey, and Egypt would come to Hyderabad''s rescue, with the Arab League extending its support.\n2. America would enter the picture, since Hyderabad served US interests as a protected outpost to check the spread of communism in South-East Asia.\n3. India, already weakened by numerous internal pr' WHERE chapter_slug = 'telangana-history-en-chapter28-police-action-operation-polo';
UPDATE theory_content SET concepts_json = concepts_json || 'oblems, would not be able to sustain the struggle — the Sikhs were demanding a separate state, and princely rulers everywhere were waiting for a good opportunity to revolt against Indian rule, with the Indian army in any case concentrated in Kashmir.\n4. Hyderabad had a secret agreement with Pakistan, under which Pakistan would build two air bases in Goa from which attacks would be launched on India.\n5. Within a few days, the port of Bandar would be captured, after which Hyderabad would establish direct relations with foreign countries.", "free": false}, {"partNumber": 7, "conceptId": "telangana-history-en-chapter28-police-action-operation-polo-p7", "partName": "Hyderabad''s Appeal to the United Nations", "bodyMd": "- Hyderabad took its case to the UN Security Council. The Nizam government''s committee before the UN Security Council was headed by Hyderabad''s External Affairs Minister, **Moin Nawaz Jung**.\n- Before this, on **21st August, 1948**, the Nizam government had already sent a complaint against the Indian government via cablegram to the UN Security Council, under **Article 35(2)**.\n- **Sir Walter Monckton** was engaged to assist the Nizam''s case before the Security Council; the UN Security Council president at the time was **Alexander Cadogan**.\n- The Indian government sent its own delegation to the Security Council under **Sir Ramaswamy Mudaliar** of Madras.\n- The Nizam wrote personally to several world leaders seeking support against the merger — **British Emperor George VI**, **British Prime Minister Clement Attlee**, **British Opposition Leader Winston Churchill**, and **American President Harry S. Truman** — all of whom expressed their inability to help.\n- While the Hyderabad case was still under the Security Council''s consideration, the Indian government carried out its police action on Hyderabad. News of this, as reported in the foreign press, was read out to the Security Council by Moin Nawaz Jung, leading Hyderabad''s delegation.\n- Sir Ramaswamy Mudaliar, leading the Indian delegation, argued that Hyderabad was India''s internal problem and did not fall within the Security Council''s jurisdiction.\n- As these arguments continued at the UN, the Police Action was completed on **17th September**. [Discrepancy between sources: Source 1 (English) — the Nizam withdrew his UN complaint on 22nd September, 1948; Source 2 (Telugu) — the Nizam informed the Security Council by telegram, on the same day the Police Action concluded (17th September), that he was withdrawing the case — needs verification.]\n\nAngered by the Nizam''s actions, and following the death of **Muhammad Ali Jinnah** — the Nizam''s biggest supporter — the Indian government ordered military action two days later.", "free": false}, {"partNumber": 8, "conceptId": "telangana-history-en-chapter28-police-action-operation-polo-p8", "partName": "Operation Polo — the Police Action", "bodyMd": "### Was It a War?\nThis was not a war in the true sense — the Nizam''s soldiers barely fought anywhere. In reality, Hyderabad possessed no army of its own; for the second Nizam''s entire reign, the force had effectively been under British control, and whatever army the Nizam did have was thoroughly weak. All the military cantonments in Hyderabad were dominated by British troops.\n\nHyderabad''s army had no modern weapons, and there were no factories capable of producing war material. Two hundred years of dependence had reduced Hyderabad''s military strength to a mere token force. It was the Razakars — not the Nizam''s army — who fought and resisted the police action.\n\n### The Operation\n- The Indian government informed the Pakistani High Commissioner and the American government that \"Operation Polo\" was being conducted in Hyderabad to stop the atrocities of communists and Razakars and to establish peace.\n- It was termed a **\"Police Action\"** rather than a military action because, under UN principles, one independent country cannot conduct a military action against another independent country. Accordingly, the expenses of the operation were booked under the Education Department''s accounts rather than the Home or Defence Ministry''s.\n- The operation was named \"Police Action\" by **C. Rajagopalachari**; it is also referred to as **Operation Polo** or **Operation Caterpillar** in a military sense, and as the **Goddard Plan**.\n- **Started:** 13th September, 1948. **Ended:** 17th September, 1948. **Planned by:** E.N. Goddard.\n\n**Key figures during Operation Polo**\n\n| Role | Person |\n|---|---|\n| Indian Governor-General | C. Rajagopalachari |\n| Indian Army Chief | Sir Roy Bucher |\n| Indian Defence Minister | Baldev Singh |\n| Indian Home Minister | Sardar Vallabhbhai Patel |\n| Indian Secretary of Princely States | V.P. Menon |\n| Hyderabad Army Commander-in-Chief | General El Edroos |\n| Hyderabad Prime Minister | Mir Laiq Ali |\n| Hyderabad Police Commissioner | Deen Yar Jung |\n\n- The operation was conducted under Southern Commander **Lt. General Maharaja Rajendra Singh**, who divided the army into the following forces:\n\n| Sector | Commanding Officer |\n|---|---|\n| Solapur | J.N. Chaudhari |\n| Vijayawada | A.A. Rudra |\n| Berar/Hospet | Shiva Dattu Singh |\n| Bombay | D.S. Dhar |\n\n- **Pune airbase**, under the command of **Mukherjee**, was used to support attacks with aircraft.\n\n### Course of the Operation\n- **13th September, 1948** — Military attacks began from all corners of Hyderabad. Lt. Col. Ram Singh, of the strike force under J.N. Chaudhari, annexed **Naldurg** (in Maharashtra), **Sholapur**, **Thamalwadi**, and **Thuljapur**. The same day, under Major Rudra''s leadership, the army occupied **Bonakallu**. Naldurg was the first city annexed as part of Operation Polo.\n- **14th September** — The Indian army occupied **Doulatabad, Jalna, Manikhed,** and **Kanegao**.\n- **15th September** — Forces led by Major General Rudra entered **Old Suryapet** village.\n- **16th September** — **Zahirabad, Hingoli, Raichur, Parbhani, Koppal, Munirabad,** and other towns were occupied.\n- Meanwhile, Hyderabad''s military commander **Sayyed Ahmed El Edroos**, who had been secretly passing updates to the Indian army, ordered Nizam forces to fall back rather than fight. This allowed the Indian army under Major General **J.N. Chaudhari** to enter Hyderabad quickly, and without El Edroos''s cooperation this rapid advance would not have been possible.\n- Had the matter instead been taken up before the UN Security Council on the evening of 17th September, Hyderabad might have retained an independent status, similar to the earlier position of Jammu & Kashmir.\n- Prime Minister **Mir Laiq Ali**, before resigning his post, suggested destroying all secret documents in his office and the Nizam''s office.\n- He also instructed **General Mustak Ahmed Khan**, Hyderabad''s agent in Pakistan, to transfer all the funds in his office to his own account, and sent a telegram to the London Agent-General, **Mir Nawab Jung**, to credit £5,000 to his account — saying the money could be used for a future independence movement.\n\n### Fall of the Nizam''s Government\n- **17th September, 1948** — Nizam **Osman Ali Khan** met K.M. Munshi at the **Lake View Guest House**, Hyderabad, and told him that Hyderabad state would merge with the Indian Union.\n- The same evening, at **7 p.m.**, the Nizam announced on Deccan Radio, in the name of Indian Governor-General Rajagopalachari, that Hyderabad had become part of the Indian Union, and that Indian army camps would be permitted at **Bollaram** and **Secunderabad**. He also ordered the immediate release of **Swamy Ramananda Tirtha**, president of the State Congress.\n- **Deccan Radio** was the Nizam government''s official radio station; its first director was **Fazlur Rehman**.\n- **18th September, 1948** — Hyderabad Commander-in-Chief **El Edroos**, along with his troops, surrendered before Indian Major General **J.N. Chaudhari**. Under military rules, Chaudhari — being the first Indian officer to enter Hyderabad — was appointed Hyderabad''s Military General.\n- The same day, Razakar leader **Qasim Razvi** was arrested and imprisoned at the military camp in **Tirumalgiri**, and Prime Minister Laiq Ali was placed under house arrest. Nizam Osman Ali Khan welcomed **Sardar Vallabhbhai Patel** at **Begumpet Airport** on his visit to the state.\n- **22nd September, 1948** — the Nizam formally withdrew his complaint against the Indian government from the United Nations (see discrepancy note above regarding the withdrawal date).\n\n### Remembrance of the Day\n- In **Karnataka**, 17th September is observed as **Hyderabad–Karnataka Liberation Day**; in **Maharashtra**, as **Marathwada Sangram Mukti Divas**.\n- In **Telangana**, communists and Muslims refer to 17th September as **\"Betrayal Day,\"** while others call it **Telangana Liberation Day**.", "free": false}, {"partNumber": 9, "conceptId": "telangana-history-en-chapter28-police-action-operation-polo-p9", "partName": "Aftermath of Operation Polo", "bodyMd": "The entire military action was executed so swiftly and effectively that it can fairly be called a nearly bloodless conquest completed within a week. Indian forces subdued Hyderabad in a matter of days.\n\nThe Razakar organisation, which had prospered on the strength of religious extremism, vanished into thin air without a trace — leaving behind no compensation, no accountability, for its actions.\n\n**Casualties:** During the Police Action, roughly **2,000 Razakars** were killed and **4,500 people** were arrested, according to the account left by Major General J.N. Chaudhari, who successfully led the operation, in his memoir. The Police Action concluded within four days.\n\nAs the Police Action progressed, **Khasim Razvi** — who had postured as a **\"Field Marshal\"** while whipping up the Razakars — came to be nicknamed a **\"Paper Tiger.\"** In his final message broadcast on Deccan Radio, Razvi admitted defeat, told people not to lose heart, and said that they would have to look after their own safety since the Nizam''s forces could not withstand India''s military strength.\n\n- As the Indian army entered Hyderabad, Razvi hoped to escape to Pakistan and stood ready at the airport, but the aircraft left before he could board, and he was caught. He was given a seven-year prison sentence in the **Bibinagar case**.\n- The State Congress held a majority in the state and enjoyed public confidence, so responsibility for state administration would naturally have passed to it after the Police Action.\n- However, because of factional splits within Congress and the strength of pro-communist elements, along with a lack of confidence among some that the State Congress could pursue consistent policies, the party was not handed administrative authority at that stage.\n- **Pandit Jawaharlal Nehru** and **Sardar Vallabhbhai Patel** visited Hyderabad and received a grand welcome.\n- It was decided that, since the State Congress could not immediately take over administration, a provisional government should be set up, and Major General **J.N. Chaudhari** was appointed Military Governor.\n- People initially welcomed the military government wholeheartedly. However, the police and military administration filled most official posts with a large number of officers brought in from Madras and Bombay rather than from the local population.", "free": false}, {"partNumber": 10, "conceptId": "telangana-history-en-chapter28-police-action-operation-polo-p10", "partName": "J.N. Chaudhari''s Military Rule and the Sundarlal Committee (1948–49)", "bodyMd": "- **18th September, 1948** — **Jayanto Nath Chaudhari** took charge as Hyderabad''s Military Governor in the presence of Jawaharlal Nehru; his period of rule is dated from **24th September, 1948 to 31st December, 1949**.\n\n**Working committee of the Military Governor**\n\n| Role | Person |\n|---|---|\n| Military Governor | J.N. Chaudhari |\n| Chief Civil Administrator | D.S. Bakley |\n| Additional Chief Civil Administrator | D.R. Pradhan |\n\n- Chaudhari was born in **Haripura, Bengal**, and had served in the British army at Secunderabad''s Bison Division, then the largest military station in India. He took part in the **Second World War**, and later served as Indian Army Chief during the **1965 war with Pakistan**.\n\n### Chaudhari''s Farmana (6th February, 1949)\n- The Nizam''s currency, **Hali Sikka**, was to be banned (it was completely withdrawn on **1st April, 1955**).\n- The Nizam''s personal lands, known as **Sarf-e-Khas**, were taken over by the government, with **₹3 crore** paid as compensation.\n- Government institutions across the state were given holidays on **Sunday** instead of **Friday**.\n- In **August 1949**, the **\"Hyderabad State Abolition of Jagirdars & Regulation Act\"** was passed, under which all Jagir lands were taken over by the government.\n\n### Attacks on Communists and Muslims\n- During Operation Polo and under the Chaudhari government, the Indian military indiscriminately attacked Communists and Muslims — hundreds of Communists were killed and thousands of Muslims were massacred.\n- These attacks were brought to Nehru''s notice by journalist **Younis Salim**, prompting Nehru to appoint the **Sundarlal Committee** in **October 1949** to investigate.\n\n## The Sundarlal Committee (1949)\n\n| Role | Person |\n|---|---|\n| Chairman | Pandit Sundarlal |\n| Member | Khazi Abdul Gaffar |\n| Member | Maulana Abdul Misri |\n\n- The committee visited Hyderabad, met Hindus, Muslims, Congress leaders, and students, and investigated the attacks. It began its investigation on **29th November, 1949** and submitted its report to the government on **21st December, 1949**.\n- According to the report, nearly **40,000 people** died in Hyderabad state after the Police Action.\n- The government did not release the report in full; it is now held at the **Nehru Memorial Museum & Library**, Delhi.\n- Alongside the Sundarlal Committee, the conditions of Muslims in Hyderabad were separately studied by **Farid Mirza**.\n- During Operation Polo, *Times* magazine reporter **Ramesh Thapar** visited Hyderabad and wrote the book *Hyderabad Toofan*.", "free": false}, {"partNumber": 11, "conceptId": "telangana-history-en-chapter28-police-action-operation-polo-p11", "partName": "M.K. Vellodi''s Civil Government", "bodyMd": "- After the Sundarlal Committee''s report was submitted in December 1949, the central government removed **J.N. Chaudhari**.\n- In his place, the ICS officer **M.K. Vellodi** (full name Mullath Kadingi Vellodi Menon), from Kerala, was appointed Chief Minister of Hyderabad state, ruling from **26th January, 1950 to 6th March, 1952**.\n- **26th January, 1950** — Nizam Osman Ali Khan was appointed **Hyderabad Raj Pramukh**, a position he held until the formation of Andhra Pradesh on **1st November, 1956**.\n- Nizam Osman Ali Khan later contested and won general Lok Sabha elections in' WHERE chapter_slug = 'telangana-history-en-chapter28-police-action-operation-polo';
UPDATE theory_content SET concepts_json = concepts_json || ' **1957 and 1962**. He died on **24th February, 1967**, and was buried at the King Kothi Palace; his tomb is named the **\"Judi Mosque.\"**\n\n**Ministers in M.K. Vellodi''s Government**\n\n| Minister | Portfolio |\n|---|---|\n| M.K. Vellodi | Civil Administrator (Chief Minister) |\n| Burgula Ramakrishna Rao | Education, Revenue, Excise |\n| M. Seshadri | Home, Communication & Law |\n| V.B. Raju | Labour, Customs, Industries & Housing |\n| Mulchand Gandhi | Medical, Health & Regional Institutions |\n| Yar Jung Bahadur | Public Works |\n| CVS Rao | Finance & Commerce |\n| Vinayakarao Vidyalankar | Agriculture, Veterinary |\n\n### Key Points of Vellodi''s Administration\n- **Sir Ramaswamy Mudaliar**, India''s representative at the UNO in 1949, announced that a civil administration had been formed in Hyderabad state and that the Nizam now stood only as its constitutional head.\n- **Burgula Narsinga Rao** stated at the same time that, since a civil administrative government had been formed, the \"Hyderabad Dominion\" no longer existed, and the UNO should therefore drop the question of Hyderabad''s independence.\n- **Telugu and English** replaced **Urdu** as the state''s official languages; Andhra people from Madras province benefited from this change by securing a large number of jobs in Hyderabad state, at the expense of the local population.\n- Land records that had existed in Urdu were translated into English; in this process, many land rights were misappropriated, records were spoiled, and the lands of Hyderabad state were exploited.\n- **April 1952** — Hyderabad and Secunderabad Municipal Corporations were formed; **Madapati Hanumantha Rao** became Hyderabad''s first Mayor, and **Vasudeva Mudaliar** became Secunderabad''s first Mayor.\n- Hyderabad''s **first general elections** were held in **1952**, in which **Burgula Ramakrishna Rao** was elected Chief Minister.\n\n## Key Books on Hyderabad''s Integration Movement\n\n| Book | Author |\n|---|---|\n| The End of an Era | K.M. Munshi |\n| Tragedy of Hyderabad | Laiq Ali |\n| Hyderabad in Retrospect | Ali Yavar Jung |\n| Hyderabad of the Seven Loaves | General El Edroos |\n| Destruction of Hyderabad | A.G. Nurani |\n| Hyderabad Swatantra Porata Smruthulu | Swamy Ramananda Tirtha |\n| Veera Telangana – Na Anubhavalu | Raavi Narayana Reddy |\n| History of Hyderabad Independence | Veldurthi Manikya Rao |\n| Integration of Indian States | V.P. Menon |\n| Operation Polo | J.N. Chaudhari |\n| The Last Nizam – The Fallen Empire | Zubaida Yazdani |\n| Hyderabad of Introspect | Maulvi Sayyed Mehdi |\n| Telangana: The Era of Mass Politics | B. Narsing Rao |\n| Hyderabad Under Salar Jung | Maulvi Chirag Ali |\n| Hyderabad Toofan | Ramesh Thapar |", "free": false}]' WHERE chapter_slug = 'telangana-history-en-chapter28-police-action-operation-polo';
